function validate([candies, k]) {
  if (!Array.isArray(candies) || candies.length < 1 || candies.length > 100000) return 'candies needs 1 to 100000 piles.';
  if (candies.some(v => !Number.isInteger(v) || v < 1 || v > 10000000)) return 'Each pile holds between 1 and 10^7 candies.';
  if (!Number.isInteger(k) || k < 1 || k > 1000000000000) return 'k is between 1 and 10^12.';
  return null;
}

