function maximumCandies(candies, k) {
  let low = 1;
  let high = Math.max(...candies);
  let best = 0;

  while (low <= high) {
    const share = Math.floor((low + high) / 2);
    let children = 0;
    for (const pile of candies) {
      children += Math.floor(pile / share);
    }
    if (children >= k) {
      best = share;
      low = share + 1;
    } else {
      high = share - 1;
    }
  }
  return best;
}

