function maximumCandies(candies, k) {
  const total = candies.reduce((a, b) => a + b, 0);
  if (total < k) return 0;
  for (let c = Math.max(...candies); c >= 1; c--) {
    let served = 0;
    for (const p of candies) served += Math.floor(p / c);
    if (served >= k) return c;
  }
  return 0;
}

