function generate(rand, size) {
  if (size === 'small') {
    const n = 1 + Math.floor(rand() * 6);
    const top = rand() < 0.3 ? 3 : 20;
    const candies = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
    const total = candies.reduce((a, b) => a + b, 0);
    const k = 1 + Math.floor(rand() * (total + 3));
    return [candies, k];
  }
  const n = 2000;
  const top = rand() < 0.5 ? 10000000 : 1000 + Math.floor(rand() * 100000);
  const candies = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  const total = candies.reduce((a, b) => a + b, 0);
  const pick = rand();
  const k = pick < 0.15 ? 1000000000000 : pick < 0.3 ? 1 + Math.floor(rand() * 2000) : 1 + Math.floor(rand() * total);
  return [candies, k];
}
